1	import {
2	  PromptNode,
3	  GachaPool,
4	  GachaPoolItem,
5	  WildcardRegistry,
6	  ExclusionConfig,
7	  TargetEngine,
8	  ResolvedPromptResult,
9	} from '../types/schema';
10	import { assembleCleanPrompt, assembleNegativePrompt } from './tokenSanitizer';
11	
12	/**
13	 * Randomly picks one item from a weighted or unweighted array.
14	 */
15	function pickWeighted<T extends { weight?: number } | string>(items: T[]): T | null {
16	  if (!items || items.length === 0) return null;
17	
18	  const weights = items.map((item) => (typeof item === 'object' && item.weight ? item.weight : 1.0));
19	  const totalWeight = weights.reduce((sum, w) => sum + w, 0);
20	  let random = Math.random() * totalWeight;
21	
22	  for (let i = 0; i < items.length; i++) {
23	    random -= weights[i];
24	    if (random <= 0) {
25	      return items[i];
26	    }
27	  }
28	
29	  return items[items.length - 1];
30	}
31	
32	/**
33	 * Expands `{opt1|opt2|opt3}` dynamic choice syntaxes and `__wildcard__` references recursively.
34	 */
35	export function expandWildcards(
36	  text: string,
37	  wildcards: WildcardRegistry,
38	  depth = 0
39	): string {
40	  if (depth > 5) return text; // Prevent infinite recursion
41	
42	  // 1. Resolve {a|b|c} choices
43	  let result = text.replace(/\{([^{}]+)\}/g, (_, group) => {
44	    const choices = group.split('|').map((s: string) => s.trim());
45	    return choices[Math.floor(Math.random() * choices.length)] || '';
46	  });
47	
48	  // 2. Resolve __wildcard__ tokens
49	  result = result.replace(/__([a-zA-Z0-9_-]+)__/g, (match, key) => {
50	    const pool = wildcards[match] || wildcards[key] || wildcards[`__${key}__`];
51	    if (pool && pool.length > 0) {
52	      const picked = pickWeighted(pool);
53	      const tokenStr = typeof picked === 'object' ? picked.token : String(picked || '');
54	      return expandWildcards(tokenStr, wildcards, depth + 1);
55	    }
56	    return match;
57	  });
58	
59	  return result;
60	}
61	
62	/**
63	 * Resolves the full prompt graph, rolling gacha pools, applying weights, and assembling positive/negative prompts.
64	 */
65	export function resolvePromptGraph(params: {
66	  activeNodes: PromptNode[];
67	  nodeWeights: Record<string, number>;
68	  gachaPools: GachaPool[];
69	  activeGachaPoolIds: string[];
70	  wildcards: WildcardRegistry;
71	  exclusions: ExclusionConfig;
72	  targetEngine: TargetEngine;
73	  customPositive?: string;
74	  customNegative?: string;
75	  seed?: number;
76	}): ResolvedPromptResult {
77	  const {
78	    activeNodes,
79	    nodeWeights,
80	    gachaPools,
81	    activeGachaPoolIds,
82	    wildcards,
83	    exclusions,
84	    targetEngine,
85	    customPositive = '',
86	    customNegative = '',
87	    seed = Math.floor(Math.random() * 1000000000),
88	  } = params;
89	
90	  const rawChunks: { token: string; weight: number }[] = [];
91	  const activeTags: string[] = [];
92	  const gachaDraws: { poolId: string; poolName: string; items: string[] }[] = [];
93	
94	  // 1. Process active nodes
95	  for (const node of activeNodes) {
96	    const weight = nodeWeights[node.id] !== undefined ? nodeWeights[node.id] : (node.defaultWeight || 1.0);
97	    const expandedToken = expandWildcards(node.token, wildcards);
98	    rawChunks.push({ token: expandedToken, weight });
99	
100	    if (node.tags) {
101	      activeTags.push(...node.tags);
102	    }
103	
104	    if (node.loras) {
105	      for (const lora of node.loras) {
106	        rawChunks.push({ token: lora, weight: 1.0 });
107	      }
108	    }
109	  }
110	
111	  // 2. Process Gacha Pools (both explicitly active and attached to active nodes)
112	  const poolsToDraw = new Map<string, GachaPool>();
113	
114	  for (const pool of gachaPools) {
115	    if (activeGachaPoolIds.includes(pool.id)) {
116	      poolsToDraw.set(pool.id, pool);
117	    }
118	  }
119	
120	  for (const node of activeNodes) {
121	    if (node.gachaPoolId) {
122	      const pool = gachaPools.find((p) => p.id === node.gachaPoolId);
123	      if (pool) {
124	        poolsToDraw.set(pool.id, pool);
125	      }
126	    }
127	  }
128	
129	  // Execute Gacha Draws
130	  poolsToDraw.forEach((pool) => {
131	    const drawnTokens: string[] = [];
132	    const count = Math.max(1, pool.drawCount || 1);
133	
134	    for (let i = 0; i < count; i++) {
135	      if (pool.items.length === 0) continue;
136	      const picked = pickWeighted(pool.items);
137	      if (!picked) continue;
138	
139	      const tokenStr = typeof picked === 'object' ? (picked as GachaPoolItem).token : String(picked);
140	      const weight = typeof picked === 'object' ? (picked as GachaPoolItem).weight || 1.0 : 1.0;
141	      const expanded = expandWildcards(tokenStr, wildcards);
142	
143	      rawChunks.push({ token: expanded, weight });
144	      drawnTokens.push(expanded);
145	    }
146	
147	    if (drawnTokens.length > 0) {
