import React from 'react';
import { PromptNode, Rarity } from '../../types/schema';
import { useStudioStore } from '../../store/useStudioStore';
import { Plus, Minus, Flame, Sparkles, Tag } from 'lucide-react';

interface NodeCardProps {
  node: PromptNode;
}

const RARITY_STYLES: Record<Rarity, { border: string; bg: string; badge: string; text: string }> = {
  SSR: {
    border: 'border-hazard-crimson/60 hover:border-hazard-crimson',
    bg: 'bg-gradient-to-br from-hazard-crimson/10 to-hazard-amber/10',
    badge: 'bg-gradient-to-r from-hazard-crimson to-hazard-amber text-white font-bold',
    text: 'text-hazard-amber',
  },
  SR: {
    border: 'border-hazard-cyan/50 hover:border-hazard-cyan',
    bg: 'bg-hazard-cyan/5',
    badge: 'bg-hazard-cyan text-black font-semibold',
    text: 'text-hazard-cyan',
  },
  R: {
    border: 'border-hazard-purple/50 hover:border-hazard-purple',
    bg: 'bg-hazard-purple/5',
    badge: 'bg-hazard-purple text-white font-medium',
    text: 'text-hazard-purple',
  },
  N: {
    border: 'border-hazard-border hover:border-hazard-borderHover',
    bg: 'bg-hazard-card',
    badge: 'bg-hazard-cardHover text-hazard-textMuted',
    text: 'text-hazard-textMuted',
  },
};

export const NodeCard: React.FC<NodeCardProps> = ({ node }) => {
  const { activeNodeIds, nodeWeights, toggleNode, setNodeWeight } = useStudioStore();

  const isActive = activeNodeIds.includes(node.id);
  const currentWeight = nodeWeights[node.id] !== undefined ? nodeWeights[node.id] : (node.defaultWeight || 1.0);
  const rarity = node.rarity || 'N';
  const rarityStyle = RARITY_STYLES[rarity];

  const handleWeightDelta = (e: React.MouseEvent, delta: number) => {
    e.stopPropagation();
    setNodeWeight(node.id, currentWeight + delta);
  };

  return (
    <div
      onClick={() => toggleNode(node.id)}
      className={`relative flex flex-col justify-between p-3.5 rounded-xl border transition-all duration-200 cursor-pointer select-none group ${
        isActive
          ? `border-hazard-gold bg-hazard-cardHover shadow-hazard-glow ring-1 ring-hazard-gold/50`
          : `${rarityStyle.border} ${rarityStyle.bg} hover:bg-hazard-cardHover/70`
      }`}
    >
      {/* Top Meta Bar: Rarity, Label & Gacha icon */}
      <div>
        <div className="flex items-center justify-between gap-2 mb-1.5">
          <span className={`text-[10px] px-1.5 py-0.5 rounded tracking-wider uppercase font-mono ${rarityStyle.badge}`}>
            {rarity}
          </span>

          <div className="flex items-center gap-1">
            {node.gachaPoolId && (
              <span title="Linked to Gacha Pool" className="p-1 rounded bg-hazard-crimson/20 text-hazard-crimson text-xs">
                <Flame className="w-3 h-3 animate-pulse" />
              </span>
            )}
            {isActive && (
              <span className="w-2 h-2 rounded-full bg-hazard-gold animate-ping" />
            )}
          </div>
        </div>

        {/* Node Name */}
        <h4 className={`text-xs font-semibold tracking-wide line-clamp-1 ${isActive ? 'text-hazard-gold' : 'text-hazard-textBright group-hover:text-white'}`}>
          {node.label}
        </h4>

        {/* Token Preview */}
        <p className="text-[11px] font-mono text-hazard-textMuted line-clamp-2 mt-1 leading-relaxed">
          {node.token}
        </p>
      </div>

      {/* Bottom Bar: Tags & Weight Steppers */}
      <div className="flex items-center justify-between mt-3 pt-2 border-t border-hazard-border/50">
        {/* Tags or description */}
        <div className="flex items-center gap-1 overflow-hidden">
          {node.tags && node.tags.slice(0, 2).map((tag) => (
            <span key={tag} className="text-[9px] px-1.5 py-0.5 rounded bg-hazard-void text-hazard-textMuted font-mono">
              #{tag}
            </span>
          ))}
        </div>

        {/* Weight Adjuster */}
        <div
          onClick={(e) => e.stopPropagation()}
          className="flex items-center gap-1 bg-hazard-void/80 border border-hazard-border rounded-md px-1.5 py-0.5"
        >
          <button
            onClick={(e) => handleWeightDelta(e, -0.05)}
            className="text-hazard-textMuted hover:text-white p-0.5 transition"
            title="Decrease Weight (-0.05)"
          >
            <Minus className="w-2.5 h-2.5" />
          </button>

          <span className={`text-[10px] font-mono font-bold min-w-[28px] text-center ${currentWeight !== 1.0 ? 'text-hazard-gold' : 'text-hazard-textMuted'}`}>
            {currentWeight.toFixed(2)}
          </span>

          <button
            onClick={(e) => handleWeightDelta(e, 0.05)}
            className="text-hazard-textMuted hover:text-white p-0.5 transition"
            title="Increase Weight (+0.05)"
          >
            <Plus className="w-2.5 h-2.5" />
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useStudioStore } from '../../store/useStudioStore';
import {
  Copy,
  Check,
  Sparkles,
  ShieldAlert,
  Layers,
  ChevronUp,
  ChevronDown,
  Terminal,
} from 'lucide-react';

export const OutputPanel: React.FC = () => {
  const {
    lastResolved,
    customPositive,
    customNegative,
    setCustomPositive,
    setCustomNegative,
  } = useStudioStore();

  const [copiedType, setCopiedType] = useState<'pos' | 'neg' | 'lora' | 'all' | null>(null);
  const [isExpanded, setIsExpanded] = useState(true);

  if (!lastResolved) return null;

  const copyToClipboard = (text: string, type: 'pos' | 'neg' | 'lora' | 'all') => {
    navigator.clipboard.writeText(text);
    setCopiedType(type);
    setTimeout(() => setCopiedType(null), 1800);
  };

  const fullPromptCombined = `${lastResolved.positivePrompt}\n\nNegative Prompt:\n${lastResolved.negativePrompt}`;

  return (
    <div className="border-t border-hazard-border bg-hazard-card/95 backdrop-blur-md shrink-0 transition-all duration-300">
      {/* Top Bar / Collapse Toggle */}
      <div className="flex items-center justify-between px-4 py-2 bg-hazard-void border-b border-hazard-border/50">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider text-hazard-gold">
            <Terminal className="w-3.5 h-3.5" />
            <span>Prompt Output Matrix</span>
          </div>

          <div className="flex items-center gap-2 text-[11px] font-mono">
            <span className="px-2 py-0.5 rounded bg-hazard-card border border-hazard-border text-hazard-textBright">
              Tokens: <strong className="text-hazard-gold">{lastResolved.tokenCount}</strong>
            </span>
            <span className="px-2 py-0.5 rounded bg-hazard-card border border-hazard-border text-hazard-cyan">
              LoRAs: <strong>{lastResolved.loras.length}</strong>
            </span>
            {lastResolved.gachaDraws.length > 0 && (
              <span className="px-2 py-0.5 rounded bg-hazard-card border border-hazard-border text-hazard-crimson">
                Gacha Procs: <strong>{lastResolved.gachaDraws.length}</strong>
              </span>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2">
          {/* Quick Copy Full */}
          <button
            onClick={() => copyToClipboard(fullPromptCombined, 'all')}
            className="flex items-center gap-1.5 px-3 py-1 bg-hazard-gold/10 border border-hazard-gold/30 hover:bg-hazard-gold/20 text-hazard-gold text-xs font-semibold rounded transition"
          >
            {copiedType === 'all' ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
            <span>{copiedType === 'all' ? 'Copied Full!' : 'Copy Master (Pos + Neg)'}</span>
          </button>

          <button
            onClick={() => setIsExpanded(!isExpanded)}
            className="p-1 text-hazard-textMuted hover:text-white transition"
          >
            {isExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronUp className="w-4 h-4" />}
          </button>
        </div>
      </div>

      {/* Expanded Content Area */}
      {isExpanded && (
        <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[320px] overflow-y-auto">
          {/* Positive Prompt Block */}
          <div className="flex flex-col gap-1.5">
            <div className="flex items-center justify-between">
              <label className="flex items-center gap-1.5 text-xs font-semibold text-hazard-gold">
                <Sparkles className="w-3.5 h-3.5" />
                <span>Positive Prompt</span>
              </label>

              <button
                onClick={() => copyToClipboard(lastResolved.positivePrompt, 'pos')}
                className="flex items-center gap-1 text-[11px] text-hazard-textMuted hover:text-hazard-gold transition"
              >
                {copiedType === 'pos' ? <Check className="w-3 h-3 text-hazard-gold" /> : <Copy className="w-3 h-3" />}
                <span>{copiedType === 'pos' ? 'Copied!' : 'Copy Positive'}</span>
              </button>
            </div>

            <div className="p-2.5 bg-hazard-void rounded-lg border border-hazard-border/80 text-xs font-mono text-hazard-textBright select-all leading-relaxed whitespace-pre-wrap max-h-24 overflow-y-auto">
              {lastResolved.positivePrompt || <span className="text-hazard-textMuted">No positive tokens selected...</span>}
            </div>

            {/* Custom Positive Input */}
            <input
              type="text"
              placeholder="Inject custom positive tokens..."
              value={customPositive}
              onChange={(e) => setCustomPositive(e.target.value)}
              className="w-full bg-hazard-void/60 border border-hazard-border px-2.5 py-1 text-xs text-hazard-textBright rounded outline-none focus:border-hazard-gold"
            />
          </div>

          {/* Negative Prompt Block */}
          <div className="flex flex-col gap-1.5">
            <div className="flex items-center justify-between">
              <label className="flex items-center gap-1.5 text-xs font-semibold text-hazard-crimson">
                <ShieldAlert className="w-3.5 h-3.5" />
                <span>Negative Prompt (Exclusions Applied)</span>
              </label>

              <button
                onClick={() => copyToClipboard(lastResolved.negativePrompt, 'neg')}
                className="flex items-center gap-1 text-[11px] text-hazard-textMuted hover:text-hazard-crimson transition"
              >
                {copiedType === 'neg' ? <Check className="w-3 h-3 text-hazard-crimson" /> : <Copy className="w-3 h-3" />}
                <span>{copiedType === 'neg' ? 'Copied!' : 'Copy Negative'}</span>
              </button>
            </div>

            <div className="p-2.5 bg-hazard-void rounded-lg border border-hazard-border/80 text-xs font-mono text-hazard-textMuted select-all leading-relaxed whitespace-pre-wrap max-h-24 overflow-y-auto">
              {lastResolved.negativePrompt || <span className="text-hazard-textMuted">No negative tokens...</span>}
            </div>

            {/* Custom Negative Input */}
            <input
              type="text"
              placeholder="Inject custom negative tokens..."
              value={customNegative}
              onChange={(e) => setCustomNegative(e.target.value)}
              className="w-full bg-hazard-void/60 border border-hazard-border px-2.5 py-1 text-xs text-hazard-textBright rounded outline-none focus:border-hazard-crimson"
            />
          </div>

          {/* LoRA Tags Bar if any */}
          {lastResolved.loras.length > 0 && (
            <div className="col-span-1 md:col-span-2 flex items-center justify-between p-2 bg-hazard-void/80 rounded-lg border border-hazard-border/50 text-xs">
              <div className="flex items-center gap-2 overflow-x-auto">
                <span className="text-hazard-gold font-semibold flex items-center gap-1">
                  <Layers className="w-3.5 h-3.5" /> LoRAs:
                </span>
                {lastResolved.loras.map((lora, idx) => (
                  <span key={idx} className="font-mono text-[11px] px-2 py-0.5 rounded bg-hazard-card border border-hazard-border text-hazard-textBright">
                    {lora}
                  </span>
                ))}
              </div>

              <button
                onClick={() => copyToClipboard(lastResolved.loras.join(' '), 'lora')}
                className="flex items-center gap-1 text-[11px] text-hazard-textMuted hover:text-hazard-gold shrink-0 ml-2"
              >
                {copiedType === 'lora' ? <Check className="w-3 h-3 text-hazard-gold" /> : <Copy className="w-3 h-3" />}
                <span>Copy LoRAs</span>
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { useStudioStore } from '../../store/useStudioStore';
import { GachaPoolItem } from '../../types/schema';
import { X, Flame, Check, Dices } from 'lucide-react';

interface PoolInspectorProps {
  onClose: () => void;
}

export const PoolInspector: React.FC<PoolInspectorProps> = ({ onClose }) => {
  const { gachaPools, activeGachaPoolIds, toggleGachaPool, reroll, lastResolved } = useStudioStore();

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-fadeIn">
      <div className="flex flex-col w-full max-w-2xl max-h-[85vh] bg-hazard-card border border-hazard-border rounded-2xl shadow-2xl overflow-hidden">
        {/* Modal Header */}
        <div className="flex items-center justify-between p-4 border-b border-hazard-border bg-hazard-void">
          <div className="flex items-center gap-2">
            <Flame className="w-5 h-5 text-hazard-crimson" />
            <h3 className="text-sm font-bold uppercase tracking-wider text-hazard-textBright">
              Gacha Pools & Dynamic Lotteries
            </h3>
          </div>

          <button
            onClick={onClose}
            className="p-1 text-hazard-textMuted hover:text-white rounded-lg transition"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Modal Body */}
        <div className="flex-1 p-4 overflow-y-auto space-y-4">
          <p className="text-xs text-hazard-textMuted">
            Gacha pools randomly select items during prompt generation according to their draw count and weights. Toggle which pools are actively drawn.
          </p>

          <div className="space-y-3">
            {gachaPools.map((pool) => {
              const isActive = activeGachaPoolIds.includes(pool.id);

              return (
                <div
                  key={pool.id}
                  className={`p-3.5 rounded-xl border transition ${
                    isActive
                      ? 'border-hazard-crimson/60 bg-hazard-crimson/5'
                      : 'border-hazard-border bg-hazard-void/60'
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2.5">
                      <button
                        onClick={() => toggleGachaPool(pool.id)}
                        className={`flex items-center justify-center w-5 h-5 rounded border transition ${
                          isActive
                            ? 'bg-hazard-crimson border-hazard-crimson text-white'
                            : 'border-hazard-border text-transparent'
                        }`}
                      >
                        <Check className="w-3.5 h-3.5" />
                      </button>

                      <div>
                        <h4 className="text-xs font-semibold text-hazard-textBright">
                          {pool.name}
                        </h4>
                        <p className="text-[11px] text-hazard-textMuted">
                          {pool.description} • Draws:{' '}
                          <strong className="text-hazard-gold">{pool.drawCount}</strong>
                        </p>
                      </div>
                    </div>

                    <span className="text-[10px] font-mono px-2 py-0.5 rounded bg-hazard-card border border-hazard-border text-hazard-textMuted">
                      {pool.items.length} items
                    </span>
                  </div>

                  {/* Pool Items List */}
                  <div className="mt-3 pt-2.5 border-t border-hazard-border/50 grid grid-cols-1 sm:grid-cols-2 gap-1.5">
                    {pool.items.map((item, idx) => {
                      const token = typeof item === 'object' ? (item as GachaPoolItem).token : String(item);
                      const rarity = typeof item === 'object' ? (item as GachaPoolItem).rarity || 'N' : 'N';

                      return (
                        <div
                          key={idx}
                          className="flex items-center justify-between px-2 py-1 bg-hazard-void/80 rounded border border-hazard-border/40 text-[11px] font-mono"
                        >
                          <span className="text-hazard-textMuted truncate mr-2">{token}</span>
                          <span className="text-[9px] px-1 py-0.2 rounded bg-hazard-card text-hazard-gold font-bold">
                            {rarity}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Modal Footer */}
        <div className="flex items-center justify-between p-4 border-t border-hazard-border bg-hazard-void">
          <button
            onClick={reroll}
            className="flex items-center gap-2 px-3 py-1.5 bg-hazard-gold/10 border border-hazard-gold/30 hover:bg-hazard-gold/20 text-hazard-gold text-xs font-semibold rounded-lg transition"
          >
            <Dices className="w-4 h-4" />
            <span>Test Re-Roll</span>
          </button>

          <button
            onClick={onClose}
            className="px-4 py-1.5 bg-hazard-gold text-black text-xs font-bold rounded-lg hover:brightness-110 transition"
          >
            Done
          </button>
        </div>
      </div>
    </div>
  );
};

