    loadPreset,
    setTargetEngine,
    setSeed,
    toggleSeedLock,
    reroll,
    clearSelections,
    activeNodeIds,
  } = useStudioStore();

  const engines = ['ComfyUI', 'SD_WebUI', 'NovelAI', 'Midjourney', 'Flux'] as const;

