import { create } from 'zustand';
import { immer } from 'zustand/middleware/immer';
import {
  Category,
  PromptNode,
  GachaPool,
  Preset,
  ResolvedPromptResult,
  TargetEngine,
} from '@/types/schema';
import { categoriesApi, nodesApi, poolsApi, presetsApi, graphApi } from '@/types/api';

interface StudioState {
  // Data
  categories: Category[];
  nodes: PromptNode[];
  pools: GachaPool[];
  presets: Preset[];
  isLoading: boolean;

  // Runtime state
  activePresetId: string | null;
  activeNodeIds: string[];
  nodeWeights: Record<string, number>;
  activeGachaPoolIds: string[];
  targetEngine: TargetEngine;
  customPositive: string;
  customNegative: string;
  seed: number;
  isSeedLocked: boolean;
  selectedCategoryId: string;
  lastResolved: ResolvedPromptResult | null;

  // Actions
  init: () => Promise<void>;
  toggleNode: (nodeId: string) => void;
  setNodeWeight: (nodeId: string, weight: number) => void;
  toggleGachaPool: (poolId: string) => void;
  setTargetEngine: (engine: TargetEngine) => void;
  setCustomPositive: (val: string) => void;
  setCustomNegative: (val: string) => void;
  setSeed: (seed: number) => void;
  toggleSeedLock: () => void;
  setSelectedCategory: (catId: string) => void;
  loadPreset: (presetId: string) => void;
  saveCurrentPreset: (name: string, description?: string) => Promise<void>;
  reroll: () => Promise<void>;
  clearSelections: () => void;
}

export const useStudioStore = create<StudioState>()(
  immer((set, get) => ({
    categories: [],
    nodes: [],
    pools: [],
    presets: [],
    isLoading: false,

    activePresetId: null,
    activeNodeIds: [],
    nodeWeights: {},
    activeGachaPoolIds: [],
    targetEngine: 'ComfyUI',
    customPositive: '',
    customNegative: '',
    seed: Math.floor(Math.random() * 1000000000),
    isSeedLocked: false,
    selectedCategoryId: 'all',
    lastResolved: null,

    init: async () => {
      set({ isLoading: true });
      try {
        const [categories, nodes, pools, presets] = await Promise.all([
          categoriesApi.list(),
          nodesApi.list(),
          poolsApi.list(),
          presetsApi.list(),
        ]);

        set({
          categories,
          nodes,
          pools,
          presets,
          isLoading: false,
        });

        // Load first preset if available
        if (presets.length > 0) {
          get().loadPreset(presets[0].id);
        }
      } catch (e) {
        console.error('[Studio] Init error:', e);
        set({ isLoading: false });
      }
    },

    toggleNode: (nodeId: string) => {
      set((state) => {
        const node = state.nodes.find((n) => n.id === nodeId);
        if (!node) return;

        const category = state.categories.find((c) => c.id === node.category_id);
        const isActive = state.activeNodeIds.includes(nodeId);

        if (isActive) {
          state.activeNodeIds = state.activeNodeIds.filter((id) => id !== nodeId);
        } else {
          if (category?.selection_type === 'single') {
            const otherIds = state.nodes
              .filter((n) => n.category_id === category.id)
              .map((n) => n.id);
            state.activeNodeIds = state.activeNodeIds.filter((id) => !otherIds.includes(id));
          }
          state.activeNodeIds.push(nodeId);
        }
      });
      get().reroll();
    },

    setNodeWeight: (nodeId: string, weight: number) => {
      set((state) => {
        const clamped = Math.max(0.1, Math.min(2.0, Math.round(weight * 100) / 100));
        state.nodeWeights[nodeId] = clamped;
      });
      get().reroll();
    },

    toggleGachaPool: (poolId: string) => {
      set((state) => {
        if (state.activeGachaPoolIds.includes(poolId)) {
          state.activeGachaPoolIds = state.activeGachaPoolIds.filter((id) => id !== poolId);
        } else {
          state.activeGachaPoolIds.push(poolId);
        }
      });
      get().reroll();
    },

    setTargetEngine: (engine: TargetEngine) => {
      set({ targetEngine: engine });
      get().reroll();
    },

    setCustomPositive: (val: string) => {
      set({ customPositive: val });
      get().reroll();
    },

    setCustomNegative: (val: string) => {
      set({ customNegative: val });
      get().reroll();
    },

    setSeed: (seed: number) => {
      set({ seed });
    },

    toggleSeedLock: () => {
      set((state) => {
        state.isSeedLocked = !state.isSeedLocked;
      });
    },

    setSelectedCategory: (catId: string) => {
      set({ selectedCategoryId: catId });
    },

    loadPreset: (presetId: string) => {
      const preset = get().presets.find((p) => p.id === presetId);
      if (!preset) return;

      set({
        activePresetId: preset.id,
        targetEngine: preset.target_engine || 'ComfyUI',
        activeNodeIds: [...preset.active_node_ids],
        nodeWeights: { ...preset.node_weights },
        customPositive: preset.custom_positive || '',
        customNegative: preset.custom_negative || '',
        activeGachaPoolIds: preset.active_gacha_pool_ids || [],
      });

      get().reroll();
    },

    saveCurrentPreset: async (name: string, description?: string) => {
      const {
        targetEngine,
        activeNodeIds,
        nodeWeights,
        customPositive,
        customNegative,
        activeGachaPoolIds,
      } = get();

      const newPreset: Omit<Preset, 'id' | 'created_at'> = {
        name,
        description: description || 'User saved configuration',
        target_engine: targetEngine,
        active_node_ids: activeNodeIds,
        node_weights: nodeWeights,
        custom_positive: customPositive,
        custom_negative: customNegative,
        active_gacha_pool_ids: activeGachaPoolIds,
      };

      try {
        const saved = await presetsApi.create(newPreset);
        set((state) => {
          state.presets.push(saved);
          state.activePresetId = saved.id;
        });
      } catch (e) {
        console.error('[Studio] Save preset error:', e);
      }
    },

    reroll: async () => {
      const { activePresetId, isSeedLocked, seed } = get();

      if (!activePresetId) return;

      const effectiveSeed = isSeedLocked ? seed : Math.floor(Math.random() * 1000000000);

      if (!isSeedLocked) {
        set({ seed: effectiveSeed });
      }

      try {
        const result = await graphApi.resolve(activePresetId, effectiveSeed);
        set({ lastResolved: result });
      } catch (e) {
        console.error('[Studio] Graph resolution error:', e);
      }
    },

    clearSelections: () => {
      set({
        activeNodeIds: [],
        nodeWeights: {},
        customPositive: '',
        customNegative: '',
        activePresetId: null,
      });
      get().reroll();
    },
  }))
);

import React from 'react';
import { useStudioStore } from '@/store/useStudioStore';
import { Flame, Lock, Unlock, Save, Trash2, RefreshCw, Layers, Sliders } from 'lucide-react';

interface HeaderBarProps {
  onOpenPools: () => void;
}

export const HeaderBar: React.FC<HeaderBarProps> = ({ onOpenPools }) => {
  const {
    presets,
    activePresetId,
    targetEngine,
    seed,
    isSeedLocked,
    loadPreset,
    setTargetEngine,
    setSeed,
    toggleSeedLock,
    reroll,
    clearSelections,
    activeNodeIds,
  } = useStudioStore();

  const engines = ['ComfyUI', 'SD_WebUI', 'NovelAI', 'Midjourney', 'Flux'] as const;

  return (
    <header className="flex flex-wrap items-center justify-between gap-4 p-4 border-b border-hazard-border bg-hazard-void shrink-0">
      {/* Brand */}
      <div className="flex items-center gap-3">
        <div className="flex items-center justify-center w-10 h-10 rounded-lg bg-gradient-to-br from-hazard-crimson to-hazard-amber">
          <Flame className="w-6 h-6 text-white animate-pulse" />
        </div>
        <div>
          <h1 className="text-lg font-bold tracking-wider uppercase text-hazard-textBright">
            Hazard Trigger <span className="text-xs text-hazard-gold">STUDIO</span>
          </h1>
          <p className="text-xs text-hazard-textMuted">{activeNodeIds.length} Nodes Active</p>
        </div>
      </div>

      {/* Controls */}
      <div className="flex flex-wrap items-center gap-2">
        {/* Preset Selector */}
        <select
          value={activePresetId || ''}
          onChange={(e) => loadPreset(e.target.value)}
          className="bg-hazard-card border border-hazard-border px-3 py-1 text-xs text-hazard-textBright rounded"
        >
          <option value="">Select Preset</option>
          {presets.map((p) => (
            <option key={p.id} value={p.id}>
              {p.name}
            </option>
          ))}
        </select>

        {/* Engine Selector */}
        <select
          value={targetEngine}
          onChange={(e) => setTargetEngine(e.target.value as any)}
          className="bg-hazard-card border border-hazard-border px-3 py-1 text-xs text-hazard-textBright rounded"
        >
          {engines.map((e) => (
            <option key={e} value={e}>
              {e}
            </option>
          ))}
        </select>

        {/* Seed Controls */}
        <div className="flex items-center gap-1 bg-hazard-card border border-hazard-border rounded px-2 py-1">
          <button
            onClick={toggleSeedLock}
            className={`p-1 transition ${isSeedLocked ? 'text-hazard-gold' : 'text-hazard-textMuted'}`}
            title="Lock seed"
          >
            {isSeedLocked ? <Lock className="w-4 h-4" /> : <Unlock className="w-4 h-4" />}
          </button>
          <input
            type="number"
            value={seed}
            onChange={(e) => setSeed(parseInt(e.target.value) || 0)}
            className="w-20 bg-transparent text-xs font-mono text-hazard-gold outline-none"
          />
        </div>

        {/* Action Buttons */}
        <button
          onClick={reroll}
          className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-black bg-hazard-gold rounded hover:brightness-110"
        >
          <RefreshCw className="w-4 h-4" />
          Re-Roll
        </button>

        <button
          onClick={onOpenPools}
          className="flex items-center gap-1 px-3 py-2 text-xs bg-hazard-cyan/20 border border-hazard-cyan text-hazard-cyan rounded hover:bg-hazard-cyan/30"
        >
          <Layers className="w-4 h-4" />
          Pools
        </button>

        <button
          onClick={clearSelections}
          className="p-2 text-hazard-textMuted hover:text-hazard-crimson bg-hazard-card border border-hazard-border rounded transition"
          title="Clear all"
        >
          <Trash2 className="w-4 h-4" />
        </button>
      </div>
    </header>
  );
};

import React from 'react';
import { PromptNode } from '@/types/schema';
import { useStudioStore } from '@/store/useStudioStore';
import { Plus, Minus } from 'lucide-react';

interface NodeCardProps {
  node: PromptNode;
}

export const NodeCard: React.FC<NodeCardProps> = ({ node }) => {
  const { activeNodeIds, nodeWeights, toggleNode, setNodeWeight } = useStudioStore();

  const isActive = activeNodeIds.includes(node.id);
  const currentWeight = nodeWeights[node.id] ?? node.default_weight ?? 1.0;
  const rarity = node.rarity ?? 'N';

  const rarityColors = {
    SSR: 'from-hazard-crimson to-hazard-amber',
    SR: 'bg-hazard-cyan',
    R: 'bg-hazard-purple',
    N: 'bg-hazard-cardHover',
  };

  return (
    <div
      onClick={() => toggleNode(node.id)}
      className={`relative p-3 rounded-lg border transition cursor-pointer select-none ${
        isActive
          ? 'border-hazard-gold bg-hazard-cardHover shadow-hazard-glow'
          : 'border-hazard-border bg-hazard-card hover:bg-hazard-cardHover'
      }`}
    >
      {/* Header */}
      <div className="flex items-center justify-between gap-2 mb-2">
        <span className={`text-[10px] px-2 py-0.5 rounded font-mono text-white font-bold ${
          rarity === 'SSR' ? 'bg-gradient-to-r ' + rarityColors.SSR :
          rarity === 'SR' ? 'bg-' + rarityColors.SR :
          rarity === 'R' ? 'bg-' + rarityColors.R :
          'bg-' + rarityColors.N
        }`}>
          {rarity}
        </span>
        {isActive && <span className="w-2 h-2 rounded-full bg-hazard-gold animate-ping" />}
      </div>

      {/* Label */}
      <h4 className={`text-xs font-semibold line-clamp-1 ${
        isActive ? 'text-hazard-gold' : 'text-hazard-textBright'
      }`}>
        {node.label}
      </h4>

      {/* Token */}
      <p className="text-[11px] font-mono text-hazard-textMuted line-clamp-2 mt-1">
        {node.token}
      </p>

      {/* Footer */}
      <div className="flex items-center justify-between mt-2 pt-2 border-t border-hazard-border/50">
        <div className="flex gap-1">
          {node.tags?.slice(0, 2).map((tag) => (
            <span key={tag} className="text-[9px] px-1.5 py-0.5 rounded bg-hazard-void text-hazard-textMuted font-mono">
              #{tag}
            </span>
          ))}
        </div>

        {/* Weight */}
        <div className="flex items-center gap-1 bg-hazard-void rounded px-1.5 py-0.5">
          <button
            onClick={(e) => {
              e.stopPropagation();
              setNodeWeight(node.id, currentWeight - 0.05);
            }}
            className="text-hazard-textMuted hover:text-white"
          >
            <Minus className="w-3 h-3" />
          </button>
          <span className={`text-[10px] font-mono font-bold w-8 text-center ${
            currentWeight !== 1.0 ? 'text-hazard-gold' : 'text-hazard-textMuted'
          }`}>
            {currentWeight.toFixed(2)}
          </span>
          <button
            onClick={(e) => {
              e.stopPropagation();
              setNodeWeight(node.id, currentWeight + 0.05);
            }}
            className="text-hazard-textMuted hover:text-white"
          >
            <Plus className="w-3 h-3" />
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useStudioStore } from '@/store/useStudioStore';
import { NodeCard } from './NodeCard';
import { Search, Grid } from 'lucide-react';

export const MatrixGrid: React.FC = () => {
  const {
    categories,
    nodes,
    activeNodeIds,
    selectedCategoryId,
    setSelectedCategory,
  } = useStudioStore();

  const [searchTerm, setSearchTerm] = useState('');

  const filteredNodes = nodes.filter((node) => {
    const matchesCategory = selectedCategoryId === 'all' || node.category_id === selectedCategoryId;
    const matchesSearch = !searchTerm.trim() ||
      node.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
      node.token.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (node.tags?.some((t) => t.toLowerCase().includes(searchTerm.toLowerCase())) ?? false);

    return matchesCategory && matchesSearch;
  });

  const activeCategory = categories.find((c) => c.id === selectedCategoryId);

  return (
    <div className="flex flex-col flex-1 overflow-hidden">
      {/* Nav Bar */}
      <div className="flex flex-wrap items-center justify-between gap-3 px-4 py-2 border-b border-hazard-border bg-hazard-card/60 shrink-0">
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1">
          <button
            onClick={() => setSelectedCategory('all')}
            className={`flex items-center gap-1 px-3 py-1 rounded text-xs font-semibold whitespace-nowrap ${
              selectedCategoryId === 'all'
                ? 'bg-hazard-gold text-black'
                : 'text-hazard-textMuted hover:text-white'
            }`}
          >
            <Grid className="w-3.5 h-3.5" />
            All ({nodes.length})
          </button>

          {categories.map((cat) => {
            const catCount = nodes.filter((n) => n.category_id === cat.id).length;
            const activeCount = nodes
              .filter((n) => n.category_id === cat.id && activeNodeIds.includes(n.id))
              .length;

            return (
              <button
                key={cat.id}
                onClick={() => setSelectedCategory(cat.id)}
                className={`flex items-center gap-1 px-3 py-1 rounded text-xs font-semibold whitespace-nowrap ${
                  selectedCategoryId === cat.id
                    ? 'bg-hazard-cardHover text-white border border-hazard-border'
                    : 'text-hazard-textMuted hover:text-white'
                }`}
                style={selectedCategoryId === cat.id ? { borderColor: cat.color } : {}}
              >
                <span style={{ color: cat.color }}>●</span>
                {cat.name}
                {activeCount > 0 && (
                  <span className="ml-1 px-1.5 py-0.2 text-[10px] font-mono rounded-full bg-hazard-gold text-black font-bold">
                    {activeCount}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        {/* Search */}
        <div className="flex items-center gap-2 bg-hazard-void border border-hazard-border rounded px-2.5 py-1 min-w-[150px]">
          <Search className="w-3.5 h-3.5 text-hazard-textMuted" />
          <input
            type="text"
            placeholder="Search..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-transparent text-xs text-hazard-textBright placeholder:text-hazard-textMuted/60 outline-none"
          />
        </div>
      </div>

      {/* Category Info */}
      {activeCategory && (
        <div className="flex items-center justify-between px-4 py-2 bg-hazard-void/50 border-b border-hazard-border/40 text-xs shrink-0">
          <div className="flex items-center gap-2">
            <span style={{ color: activeCategory.color }} className="font-bold">
              {activeCategory.name}
            </span>
            <span className="text-hazard-textMuted">• {activeCategory.description}</span>
          </div>
          <span className="text-[11px] font-mono text-hazard-textMuted">
            Mode: <span className="text-hazard-cyan font-bold uppercase">{activeCategory.selection_type} Selection</span>
          </span>
        </div>
      )}

      {/* Grid */}
      <div className="flex-1 p-4 overflow-y-auto">
        {filteredNodes.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-center text-hazard-textMuted">
            <p className="text-sm font-medium">No nodes match filter</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3.5">
            {filteredNodes.map((node) => (
              <NodeCard key={node.id} node={node} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useStudioStore } from '@/store/useStudioStore';
import { Copy, Check, Sparkles, ShieldAlert, Terminal, ChevronDown, ChevronUp } from 'lucide-react';

export const OutputPanel: React.FC = () => {
  const { lastResolved, customPositive, setCustomPositive, customNegative, setCustomNegative } =
    useStudioStore();

  const [copiedType, setCopiedType] = useState<string | null>(null);
  const [isExpanded, setIsExpanded] = useState(true);

  if (!lastResolved) return null;

  const copyToClipboard = (text: string, type: string) => {
    navigator.clipboard.writeText(text);
    setCopiedType(type);
    setTimeout(() => setCopiedType(null), 1800);
  };

  const fullPrompt = `${lastResolved.positive_prompt}\n\nNegative Prompt:\n${lastResolved.negative_prompt}`;

  return (
    <div className="border-t border-hazard-border bg-hazard-card/95 shrink-0">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2 bg-hazard-void border-b border-hazard-border/50">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider text-hazard-gold">
            <Terminal className="w-3.5 h-3.5" />
            Prompt Output
          </div>
          <div className="flex items-center gap-2 text-[11px] font-mono">
            <span className="px-2 py-0.5 rounded bg-hazard-card border border-hazard-border text-hazard-textBright">
              Tokens: <strong className="text-hazard-gold">{lastResolved.token_count}</strong>
            </span>
            <span className="px-2 py-0.5 rounded bg-hazard-card border border-hazard-border text-hazard-cyan">
              LoRAs: <strong>{lastResolved.loras.length}</strong>
            </span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => copyToClipboard(fullPrompt, 'all')}
            className="flex items-center gap-1 px-3 py-1 bg-hazard-gold/10 border border-hazard-gold/30 hover:bg-hazard-gold/20 text-hazard-gold text-xs font-semibold rounded transition"
          >
            {copiedType === 'all' ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
            {copiedType === 'all' ? 'Copied!' : 'Copy All'}
          </button>

          <button
            onClick={() => setIsExpanded(!isExpanded)}
            className="p-1 text-hazard-textMuted hover:text-white"
          >
            {isExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronUp className="w-4 h-4" />}
          </button>
        </div>
      </div>

      {/* Content */}
      {isExpanded && (
        <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[320px] overflow-y-auto">
          {/* Positive */}
          <div className="flex flex-col gap-1.5">
            <div className="flex items-center justify-between">
              <label className="flex items-center gap-1 text-xs font-semibold text-hazard-gold">
                <Sparkles className="w-3.5 h-3.5" />
                Positive
              </label>
              <button
                onClick={() => copyToClipboard(lastResolved.positive_prompt, 'pos')}
                className="flex items-center gap-1 text-[11px] text-hazard-textMuted hover:text-hazard-gold transition"
              >
                {copiedType === 'pos' ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
              </button>
            </div>
            <div className="p-2 bg-hazard-void rounded border border-hazard-border text-xs font-mono text-hazard-textBright select-all overflow-y-auto max-h-20 whitespace-pre-wrap">
              {lastResolved.positive_prompt || 'No tokens'}
            </div>
            <input
              type="text"
              placeholder="Add custom positive..."
              value={customPositive}
              onChange={(e) => setCustomPositive(e.target.value)}
              className="w-full bg-hazard-void/60 border border-hazard-border px-2 py-1 text-xs text-hazard-textBright rounded outline-none focus:border-hazard-gold"
            />
          </div>

          {/* Negative */}
          <div className="flex flex-col gap-1.5">
            <div className="flex items-center justify-between">
              <label className="flex items-center gap-1 text-xs font-semibold text-hazard-crimson">
                <ShieldAlert className="w-3.5 h-3.5" />
                Negative
              </label>
              <button
                onClick={() => copyToClipboard(lastResolved.negative_prompt, 'neg')}
                className="flex items-center gap-1 text-[11px] text-hazard-textMuted hover:text-hazard-crimson transition"
              >
                {copiedType === 'neg' ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
              </button>
            </div>
            <div className="p-2 bg-hazard-void rounded border border-hazard-border text-xs font-mono text-hazard-textMuted select-all overflow-y-auto max-h-20 whitespace-pre-wrap">
              {lastResolved.negative_prompt || 'No negatives'}
            </div>
            <input
              type="text"
              placeholder="Add custom negative..."
              value={customNegative}
              onChange={(e) => setCustomNegative(e.target.value)}
              className="w-full bg-hazard-void/60 border border-hazard-border px-2 py-1 text-xs text-hazard-textBright rounded outline-none focus:border-hazard-crimson"
            />
          </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { useStudioStore } from '@/store/useStudioStore';
import { X, Flame, Check, Dices } from 'lucide-react';

interface PoolInspectorProps {
  onClose: () => void;
}

export const PoolInspector: React.FC<PoolInspectorProps> = ({ onClose }) => {
  const { pools, activeGachaPoolIds, toggleGachaPool, reroll } = useStudioStore();

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm">
      <div className="flex flex-col w-full max-w-2xl max-h-[85vh] bg-hazard-card border border-hazard-border rounded-2xl overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-hazard-border bg-hazard-void">
          <div className="flex items-center gap-2">
            <Flame className="w-5 h-5 text-hazard-crimson" />
            <h3 className="text-sm font-bold uppercase tracking-wider text-hazard-textBright">
              Gacha Pools
            </h3>
          </div>
          <button
            onClick={onClose}
            className="p-1 text-hazard-textMuted hover:text-white rounded transition"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 p-4 overflow-y-auto space-y-3">
          {pools.map((pool) => {
            const isActive = activeGachaPoolIds.includes(pool.id);

            return (
              <div
                key={pool.id}
                className={`p-3 rounded-lg border transition ${
                  isActive ? 'border-hazard-crimson/60 bg-hazard-crimson/5' : 'border-hazard-border bg-hazard-void/60'
                }`}
              >
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => toggleGachaPool(pool.id)}
                      className={`flex items-center justify-center w-5 h-5 rounded border transition ${
                        isActive
                          ? 'bg-hazard-crimson border-hazard-crimson text-white'
                          : 'border-hazard-border'
                      }`}
                    >
                      {isActive && <Check className="w-3.5 h-3.5" />}
                    </button>
                    <div>
                      <h4 className="text-xs font-semibold text-hazard-textBright">{pool.name}</h4>
                      <p className="text-[11px] text-hazard-textMuted">
                        {pool.description} • Draws: <strong>{pool.draw_count}</strong>
                      </p>
                    </div>
                  </div>
                  <span className="text-[10px] font-mono px-2 py-0.5 rounded bg-hazard-card border border-hazard-border text-hazard-textMuted">
                    {pool.items.length} items
                  </span>
                </div>

                {/* Items */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
                  {pool.items.map((item, idx) => (
                    <div
                      key={idx}
                      className="flex items-center justify-between px-2 py-1 bg-hazard-void/80 rounded border border-hazard-border/40 text-[11px] font-mono"
                    >
                      <span className="text-hazard-textMuted truncate mr-2">{item.token}</span>
                      <span className="text-[9px] px-1 py-0.5 rounded bg-hazard-card text-hazard-gold font-bold">
                        {item.rarity || 'N'}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between p-4 border-t border-hazard-border bg-hazard-void">
          <button
            onClick={reroll}
            className="flex items-center gap-2 px-3 py-1 bg-hazard-gold/10 border border-hazard-gold/30 hover:bg-hazard-gold/20 text-hazard-gold text-xs font-semibold rounded transition"
          >
            <Dices className="w-4 h-4" />
            Test Re-Roll
          </button>
          <button
            onClick={onClose}
            className="px-4 py-1 bg-hazard-gold text-black text-xs font-bold rounded hover:brightness-110"
          >
            Done
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { HeaderBar } from './components/HeaderBar';
import { MatrixGrid } from './components/MatrixGrid';
import { OutputPanel } from './components/OutputPanel';
import { PoolInspector } from './components/PoolInspector';
import { useStudioStore } from '@/store/useStudioStore';

export const App: React.FC = () => {
  const [isPoolsOpen, setIsPoolsOpen] = useState(false);
  const { init, isLoading } = useStudioStore();

  React.useEffect(() => {
    init();
  }, [init]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-hazard-void">
        <div className="text-center">
          <div className="w-8 h-8 rounded-full border-2 border-hazard-gold border-t-transparent animate-spin mx-auto mb-4" />
          <p className="text-hazard-textMuted text-sm">Initializing Hazard Trigger...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-hazard-void text-hazard-textBright">
      <HeaderBar onOpenPools={() => setIsPoolsOpen(true)} />
      <MatrixGrid />
      <OutputPanel />
      {isPoolsOpen && <PoolInspector onClose={() => setIsPoolsOpen(false)} />}
    </div>
  );
};

