310	                    {/* Domain Header */}
311	                    <div className="flex flex-col gap-1 pb-2 border-b border-hazard-border">
312	                      <div className="flex items-center gap-2.5">
313	                        <Layers className="w-4 h-4 text-hazard-gold" />
314	                        <h2 className="text-base font-bold text-hazard-textBright uppercase tracking-wider">
315	                          {domain.displayName}
316	                        </h2>
317	                      </div>
318	                      <p className="text-xs text-hazard-textMuted font-mono pl-6">
319	                        Hierarchical Matrix Domain (Loaded from <code className="text-hazard-cyan">{domain.relPath}/</code>)
320	                      </p>
321	                    </div>
322	
323	                    {/* Data-Driven Dynamic Matrix Bar (Base Anchors + Unlocked Pools) */}
324	                    <DynamicMatrixBar domain={domain} />
325	
326	                    {/* Domain Child Component Card Selectors */}
327	                    <div className="flex flex-wrap items-start gap-8 p-6 rounded-2xl bg-hazard-card/40 border border-hazard-border/60">
328	                      {domain.files.map((file) => (
329	                        <ComponentCardSelector
330	                          key={file.relPath}
331	                          file={file}
332	                          folderName={domain.displayName}
333	                        />
334	                      ))}
335	                    </div>
336	                  </section>
337	                ))}
338	              </div>
339	            )}
340	
341	            {/* Retractable Master Compiled Prompt Output Panel (Click to Open / Click Outside to Close) */}
342	            <RetractableMasterPromptPanel onOpenAnalytics={() => setIsAnalyticsOpen(true)} />
343	          </div>
344	        )}
345	
346	        {/* Tab 2: Templates Management View */}
347	        {activeTab === 'templates' && (
348	          <TemplatesView
349	            onOpenSaveModal={() => setIsSaveModalOpen(true)}
350	            onApplyAndNavigate={handleApplyTemplateAndNavigate}
351	          />
352	        )}
353	
354	        {/* Tab 3: Reverse Engineering / Prompt Decompiler View */}
355	        {activeTab === 'reverse' && (
356	          <ReverseEngineeringView
357	            onApplyAndNavigate={() => setActiveTab('triggers')}
358	            onOpenSaveModal={() => setIsSaveModalOpen(true)}
359	          />
360	        )}
361	
362	        {/* Tab 4: Components & Options Schema Studio (Notion Table View) */}
363	        {activeTab === 'components' && <ComponentsManagerView />}
364	
365	        {/* Tab 5: Conditions & Physics Collision Studio */}
366	        {activeTab === 'conditions' && <ConditionsManagerView />}
367	
368	        {/* Placeholder Canvas for Other Tabs */}
369	        {activeTab !== 'triggers' &&
370	          activeTab !== 'templates' &&
371	          activeTab !== 'reverse' &&
372	          activeTab !== 'components' &&
373	          activeTab !== 'conditions' && (
374	            <main className="flex-1 min-h-[450px] flex flex-col items-center justify-center p-12 rounded-3xl border border-dashed border-hazard-border/80 bg-hazard-card/30 text-center">
375	              <h2 className="text-xl font-bold text-hazard-textBright tracking-wider uppercase">
376	                {activeTab} Management
377	              </h2>
378	              <p className="text-sm text-hazard-textMuted max-w-md mt-2">
379	                Autonomous object inspector and file catalog for {activeTab}.
380	              </p>
381	            </main>
382	          )}
383	      </div>
384	    </div>
385	  );
386	};
