import React, { useState, useRef, useEffect } from 'react';
import { useTriggerStore } from '../../store/useTriggerStore';
import { PromptRatingBar } from './PromptRatingBar';
import {
  Terminal,
  Dices,
  Copy,
  Check,
  ChevronUp,
  ChevronDown,
  Maximize2,
  Minimize2,
} from 'lucide-react';

interface RetractableMasterPromptPanelProps {
  onOpenAnalytics: () => void;
}

export const RetractableMasterPromptPanel: React.FC<RetractableMasterPromptPanelProps> = ({
  onOpenAnalytics,
}) => {
  const {
    compiledPrompt,
    tokenCount,
    randomCount,
    activeKeywords,
    activeExclusions,
    rerollRandoms,
  } = useTriggerStore();

  const [isOpen, setIsOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const [isRolling, setIsRolling] = useState(false);

  const panelRef = useRef<HTMLDivElement>(null);

  // Close on Outside Click
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent | TouchEvent) => {
      if (panelRef.current && !panelRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('touchstart', handleClickOutside);
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('touchstart', handleClickOutside);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen]);

