import { ItemView, WorkspaceLeaf } from 'obsidian';
import { createRoot, Root } from 'react-dom/client';
import React from 'react';
import { App } from '../app/App';
import HazardTriggerPlugin from '../main';

export const HAZARD_TRIGGER_STUDIO_VIEW = 'hazard-trigger-studio-view';

export class HazardTriggerView extends ItemView {
  private root: Root | null = null;
  private plugin: HazardTriggerPlugin;

  constructor(leaf: WorkspaceLeaf, plugin: HazardTriggerPlugin) {
    super(leaf);
    this.plugin = plugin;
  }

  getViewType(): string {
    return HAZARD_TRIGGER_STUDIO_VIEW;
  }

  getDisplayText(): string {
    return 'Hazard Trigger Studio';
  }

  getIcon(): string {
    return 'flame';
  }

  async onOpen(): Promise<void> {
    const container = this.contentEl;
    container.empty();
    container.addClass('hazard-trigger-view-container');

    this.root = createRoot(container);
    this.root.render(React.createElement(App, { app: this.app }));
  }

  async onClose(): Promise<void> {
    if (this.root) {
      this.root.unmount();
      this.root = null;
    }
    this.contentEl.empty();
  }
}

