/* ===== Hazard Trigger Dual-Wing Tournament Bracket ===== */
.bracket-wrapper {
  position: relative;
  width: 100%;
  min-height: 850px;
  height: 88vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: radial-gradient(circle at center, #0f1322 0%, #07080c 100%);
  border-radius: 24px;
  border: 1px solid #1e2230;
  box-shadow: inset 0 0 40px rgba(0, 0, 0, 0.8);
}

.bracket-canvas {
  position: relative;
  width: 100%;
  max-width: 1300px;
  height: 100%;
  aspect-ratio: 1.35 / 1;
  isolation: isolate;
}

/* Avatar Node */
.bracket-node {
  position: absolute;
  width: 58px;
  height: 58px;
  aspect-ratio: 1 / 1;
  z-index: 10;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  border: 2px solid #2a3148;
  background-color: #0f1118;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.6);
  user-select: none;
}

.bracket-node:hover {
  transform: scale(1.18);
  z-index: 30;
  border-color: #d4af37;
  box-shadow: 0 0 25px rgba(212, 175, 55, 0.45);
}

.bracket-node.node-winner {
  border-color: #d4af37;
