  { id: 'exclusions', label: 'Exclusions', icon: <ShieldAlert className="w-5 h-5" /> },
];

const handleCopy = () => {
  if (!compiledPrompt) return;
  navigator.clipboard.writeText(compiledPrompt);
  setCopied(true);
  setTimeout(() => setCopied(false), 1800);
};

const handleReroll = () => {
  setIsRolling(true);
  rerollRandoms();
  setTimeout(() => setIsRolling(false), 300);
};

