              {slotEditAvatar && (
                <div className="flex items-center gap-3 p-2 bg-hazard-void rounded-xl border border-hazard-border">
                  <img
                    src={slotEditAvatar}
                    alt="Preview"
                    className="w-10 h-10 rounded-lg object-cover"
