            </div>

            <div className="flex items-center justify-end gap-2 pt-2 border-t border-hazard-border">
              <button
                onClick={() => setEditingSlotKey(null)}
                className="px-4 py-2 text-xs font-semibold text-hazard-textMuted hover:text-white"
