const handleBulkTextChange = (text: string) => {
  setBulkText(text);
  const lines = text
    .split('\n')
    .map((l) => l.trim().replace(/^\[\[/, '').replace(/\]\]$/, '').trim())
    .filter(Boolean);

  if (lines.length === 0) return;

