                  {characters.map((c) => (
                    <option key={c.char_code} value={c.char_code}>
                      {c.char_code} - {c.canonical_name}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="text-[11px] font-mono text-hazard-textMuted uppercase font-bold mb-1 block">
                  Variant Key * (e.g. ego_01, skin_01)
                </label>
                <input
                  type="text"
                  value={formKey}
                  onChange={(e) => setFormKey(e.target.value)}
                  placeholder="e.g. ego_01"
                  className="w-full bg-hazard-void border border-hazard-border px-3 py-2 text-hazard-cyan font-mono font-bold rounded-xl outline-none focus:border-hazard-gold"
                />
              </div>

              <div className="col-span-2">
                <label className="text-[11px] font-mono text-hazard-textMuted uppercase font-bold mb-1 block">
                  Variant Display Name *
                </label>
                <input
                  type="text"
                  value={formName}
                  onChange={(e) => setFormName(e.target.value)}
