// Form State
const [formName, setFormName] = useState('');
const [formFranchise, setFormFranchise] = useState('');
const [formUniverse, setFormUniverse] = useState('');
const [formMediaType, setFormMediaType] = useState('');
const [formDescription, setFormDescription] = useState('');

const filteredWorlds = useMemo(() => {
  const q = search.trim().toLowerCase();
  return worlds.filter((w) => {
    return (
      !q ||
      w.name.toLowerCase().includes(q) ||
      (w.franchise && w.franchise.toLowerCase().includes(q)) ||
      (w.universe && w.universe.toLowerCase().includes(q)) ||
      (w.description && w.description.toLowerCase().includes(q))
    );
  });
}, [worlds, search]);

const handleOpenCreate = () => {
  setEditingWorld(null);
  setFormName('');
  setFormFranchise('');
  setFormUniverse('');
  setFormMediaType('');
  setFormDescription('');
  setIsModalOpen(true);
};

const handleOpenEdit = (w: WorldEntity) => {
  setEditingWorld(w);
  setFormName(w.name);
  setFormFranchise(w.franchise || '');
  setFormUniverse(w.universe || '');
  setFormMediaType(w.media_type || '');
  setFormDescription(w.description || '');
  setIsModalOpen(true);
};

const handleSaveWorld = async () => {
  if (!formName.trim()) return;

  const payload = {
    id: editingWorld?.id,
    name: formName.trim(),
    franchise: formFranchise.trim(),
    universe: formUniverse.trim(),
    media_type: formMediaType.trim(),
    description: formDescription.trim(),
  };

  try {
    const res = await fetch('/api/worlds', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });

    if (res.ok) {
      onRefresh();
      setIsModalOpen(false);
    }
  } catch (e) {
    console.error('[Identity] Failed to save world:', e);
  }
};

const handleDeleteWorld = async (wid: string, name: string) => {
  if (!confirm(`Delete world "${name}"? Characters assigned to this world will remain intact.`)) {

    return;
  }

  try {
    const res = await fetch(`/api/worlds/${encodeURIComponent(wid)}`, {
      method: 'DELETE',
    });
    if (res.ok) {
      onRefresh();
    }
  } catch (e) {
    console.error('[Identity] Failed to delete world:', e);
  }
};

