      setCharacters(data);
    }
  } catch (e) {
    console.error('[Identity] Failed to load characters:', e);
  } finally {
    setIsLoading(false);
  }
};

useEffect(() => {
  loadCharacters();
}, []);

const filteredCharacters = useMemo(() => {
  const q = search.trim().toLowerCase();
  return characters.filter((c) => {
    const matchesSearch =
      !q ||
      c.char_code.toLowerCase().includes(q) ||
      c.canonical_name.toLowerCase().includes(q) ||
      (c.series && c.series.toLowerCase().includes(q));

    const matchesWorld =
      worldFilter === 'all' ||
      (c.series && c.series.toLowerCase() === worldFilter.toLowerCase());

    return matchesSearch && matchesWorld;
  });
}, [characters, search, worldFilter]);

