                      <span className="font-mono text-[10px] text-hazard-gold font-bold">
                        {v.char_code}
                      </span>
                    </div>
                  </div>
                </td>
                <td className="py-2.5 px-4">
                  <span className="font-bold text-hazard-cyan bg-hazard-cyan/15 px-2 py-0.5 rounded border border-hazard-cyan/30 text-[11px]">
                    {v.variant_key}
                  </span>
                </td>
                <td className="py-2.5 px-4 font-sans font-bold text-hazard-textBright">
                  {v.variant_name}
