                  {v.prompt || <span className="text-hazard-textMuted/40">—</span>}
                </td>
                <td className="py-2.5 px-4 max-w-[200px] truncate text-hazard-textMuted" title={v.outfit}>
                  {v.outfit || <span className="text-hazard-textMuted/40">—</span>}
