                <td className="py-2.5 px-4 text-center">
                  {v.is_default ? (
                    <span className="px-2 py-0.5 rounded-full bg-hazard-gold/15 text-hazard-gold border border-hazard-gold/30 text-[10px] font-bold">
                      DEFAULT
