                      ) : (
                        <span className="text-hazard-textMuted/40">—</span>
                      )}
                    </div>
                  </td>
                  <td className="py-2.5 px-4">
                    <div className="flex flex-wrap gap-1">
                      {v.short_names && v.short_names.length > 0 ? (
