// Modal State
const [isModalOpen, setIsModalOpen] = useState(false);
const [editingVariant, setEditingVariant] = useState<VariantEntity | null>(null);
const [formCharCode, setFormCharCode] = useState('');
const [formKey, setFormKey] = useState('');
const [formName, setFormName] = useState('');
const [formPrompt, setFormPrompt] = useState('');
const [formOutfit, setFormOutfit] = useState('');
const [formIsDefault, setFormIsDefault] = useState(false);

const loadVariants = async () => {
  setIsLoading(true);
  try {
    const res = await fetch('/api/variants');
    if (res.ok) {
      const data: VariantEntity[] = await res.json();
      setVariants(data);
    }
  } catch (e) {
    console.error('[Identity] Failed to load variants:', e);
  } finally {
    setIsLoading(false);
  }
};

useEffect(() => {
  loadVariants();
}, []);

useEffect(() => {
  if (initialCharFilter) {
    setCharFilter(initialCharFilter);
  }
}, [initialCharFilter]);

const filteredVariants = useMemo(() => {
  const q = search.trim().toLowerCase();
  return variants.filter((v) => {
    const matchesSearch =
      !q ||
      v.variant_key.toLowerCase().includes(q) ||
      v.variant_name.toLowerCase().includes(q) ||
      v.char_code.toLowerCase().includes(q) ||
      v.canonical_name.toLowerCase().includes(q);

    const matchesChar =
      charFilter === 'all' ||
      v.char_code.toLowerCase() === charFilter.toLowerCase();

    return matchesSearch && matchesChar;
  });
}, [variants, search, charFilter]);

const handleOpenCreate = () => {
  setEditingVariant(null);
  setFormCharCode(charFilter !== 'all' ? charFilter : characters[0]?.char_code || 'A01');
  setFormKey(`ego_${variants.length + 1}`);
  setFormName('');
  setFormPrompt('');
  setFormOutfit('');
  setFormIsDefault(false);
  setIsModalOpen(true);
};

const handleOpenEdit = (v: VariantEntity) => {
  setEditingVariant(v);
  setFormCharCode(v.char_code);
  setFormKey(v.variant_key);
  setFormName(v.variant_name);
  setFormPrompt(v.prompt || '');
  setFormOutfit(v.outfit || '');
  setFormIsDefault(Boolean(v.is_default));
  setIsModalOpen(true);
};

const handleSaveVariant = async () => {
  if (!formCharCode.trim() || !formKey.trim() || !formName.trim()) return;

  const payload = {
    id: editingVariant?.id,
    char_code: formCharCode.trim().toUpperCase(),
    variant_key: formKey.trim(),
    variant_name: formName.trim(),
    prompt: formPrompt.trim() || '',
    outfit: formOutfit.trim() || '',
    is_default: formIsDefault,
  };

  try {
    const res = await fetch('/api/variants', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });

    if (res.ok) {
      await loadVariants();
      setIsModalOpen(false);
    }
  } catch (e) {
    console.error('[Identity] Failed to save variant:', e);
  }
};

const handleDeleteVariant = async (vid: string, name: string) => {
  if (!confirm(`Delete variant "${name}"?`)) return;

  try {
    const res = await fetch(`/api/variants/${encodeURIComponent(vid)}`, {
      method: 'DELETE',
    });
    if (res.ok) {
      await loadVariants();
    }
  } catch (e) {
    console.error('[Identity] Failed to delete variant:', e);
  }
};

